using Penny.Backend.Api.Authentication;
using Penny.Backend.Application.Authentication;
using Shouldly;
using Xunit;

namespace Penny.Backend.UnitTests.Authentication;

public sealed class SessionTokensTests
{
    [Fact]
    public void whenTokenIssued_CreateAndHash_ShouldMatchLegacyFormat()
    {
        var token = SessionTokens.Create();
        SessionTokens.IsWellFormed(token).ShouldBeTrue();
        SessionTokens.Create().ShouldNotBe(token);
        SessionTokens.NewId().Length.ShouldBe(32);
        // Generated by the legacy server's `security.hashToken`.
        SessionTokens
            .Hash("3c5a0b9e7d1f2468ace013579bdf02468ace13579bdf02468ace13579bdf0246")
            .ShouldBe("e66d4c72859c5f6e7a06e34d93dd9126a892f57ef90d2c456375f0d728d0495a");
        SessionTokens.IsWellFormed(token.ToUpperInvariant()).ShouldBeFalse();
        SessionTokens.IsWellFormed(token + "\n").ShouldBeFalse();
    }

    [Theory]
    [InlineData("127.0.0.1", "127.0.0.1")]
    [InlineData("::ffff:192.0.2.7", "192.0.2.7")]
    [InlineData("2001:db8:aa:bbcc:1:2:3:4", "2001:db8:aa:bb00::/56")]
    [InlineData("2001:db8:aa:bbff::9", "2001:db8:aa:bb00::/56")]
    public void whenClientAddressGiven_ClientKey_ShouldGroupLikeExpressRateLimit(
        string address,
        string expected
    ) => AuthRateLimit.ClientKey(System.Net.IPAddress.Parse(address)).ShouldBe(expected);
}
